// ============================================================================
// BNS (Bigwash Native Shell) - 데이터 모델
// ============================================================================
// HTTP 요청/응답, API 데이터 구조 정의

module bns_models {
    // === HTTP 요청 ===
    struct HttpRequest {
        method:      string;     // "GET", "POST", "SSE"
        path:        string;     // "/api/status", "/api/gogs", ...
        query:       string;     // "?repo=zero-copy-db"
        body:        string;     // POST 바디
        headers:     [string];   // 헤더 배열
    }

    // === HTTP 응답 ===
    struct HttpResponse {
        status_code: i32;        // 200, 404, 500
        content_type: string;    // "application/json", "text/event-stream"
        body:        string;     // 응답 바디
        is_sse:      bool;       // true면 Server-Sent Events
    }

    // === Project 상태 ===
    struct ProjectStatus {
        name:        string;     // "Zero-Copy-DB"
        phase:       i32;        // 11
        lines:       i32;        // 22439
        files:       i32;        // 56
        tests:       i32;        // 182
        status:      string;     // "✅ COMPLETE"
    }

    // === Gogs 커밋 정보 ===
    struct GogsCommit {
        hash:        string;     // "2bc0873"
        message:     string;     // "perf: 성능 최적화"
        repo:        string;     // "zero-copy-db"
        date:        string;     // "2026-03-29"
        files_changed: i32;      // 2
        insertions:  i32;        // 89
        deletions:   i32;        // 45
    }

    // === SSE 이벤트 ===
    struct SseEvent {
        event_type:  string;     // "commit", "test", "build"
        data:        string;     // JSON 문자열
        timestamp:   i64;        // Unix timestamp
    }

    // === API 응답 - Status ===
    struct ApiStatusResponse {
        last_update: string;
        projects:    [ProjectStatus];
        total_lines: i32;
        total_tests: i32;
    }

    // === API 응답 - Gogs ===
    struct ApiGogsResponse {
        recent_commits: [GogsCommit];
        repo_count:     i32;
        total_commits:  i32;
    }

    // === 에러 응답 ===
    struct ApiError {
        error:       string;
        message:     string;
        code:        i32;
    }

    // === 상수 ===
    const HTTP_OK:              i32 = 200;
    const HTTP_BAD_REQUEST:     i32 = 400;
    const HTTP_NOT_FOUND:       i32 = 404;
    const HTTP_INTERNAL_ERROR:  i32 = 500;

    const CONTENT_JSON:         string = "application/json; charset=utf-8";
    const CONTENT_SSE:          string = "text/event-stream";
    const CONTENT_TEXT:         string = "text/plain";

    // === 헬퍼 함수 ===
    func http_response_ok(body: string, content_type: string) -> HttpResponse {
        let resp: HttpResponse;
        resp.status_code = HTTP_OK;
        resp.body = body;
        resp.content_type = content_type;
        resp.is_sse = false;
        return resp;
    }

    func http_response_error(code: i32, message: string) -> HttpResponse {
        let resp: HttpResponse;
        resp.status_code = code;
        resp.body = "{\"error\": \"" + message + "\"}";
        resp.content_type = CONTENT_JSON;
        resp.is_sse = false;
        return resp;
    }

    func http_response_sse(data: string) -> HttpResponse {
        let resp: HttpResponse;
        resp.status_code = HTTP_OK;
        resp.body = "data: " + data + "\n\n";
        resp.content_type = CONTENT_SSE;
        resp.is_sse = true;
        return resp;
    }
}

# BNS Phase 2: Gogs Webhook + SSE 실시간 피드

## Context

Phase 1에서 정적 더미 응답의 4개 API 엔드포인트를 구현했음.
Phase 2 목표: Gogs 커밋 → Webhook 수신 → SSE 브로드캐스트 → 폰 화면 실시간 업데이트.

**Phase 1 발견된 버그도 함께 수정:**
- `bns_server.fl`이 `concurrent.channel_new/send/recv`를 쓰는데, `concurrent.fl` 실제 함수는 `chan_new/chan_send/chan_recv`로 이름 불일치

---

## 변경 범위

### 신규 파일 (2개)
- `bns_webhook.fl` — Gogs push 이벤트 파싱 + 서명 검증
- `bns_broadcast.fl` — SSE 브로드캐스트 (구독자 채널 풀 관리)

### 수정 파일 (2개)
- `bns_server.fl` — Channel API 이름 수정 + `/webhook/gogs` 라우트 추가
- `bns_handlers.fl` — `handle_feed()` 실시간 스트리밍으로 개선

---

## 아키텍처

```
[Gogs 커밋 발생]
      ↓
POST /webhook/gogs
      ↓
bns_webhook.parse_gogs_payload()
  - X-Gogs-Event: push 헤더 확인
  - JSON 파싱 → GogsCommit 구조체
      ↓
bns_broadcast.broadcast_event(event_json)
  - g_event_pool에 저장 (i64 인덱스)
  - g_subscriber_channels[0..N] 순회
  - 각 채널에 인덱스 전송
      ↓
GET /api/feed (SSE 연결 유지)
  - 구독자 채널 할당
  - chan_recv() 폴링
  - "data: {...}\n\n" 응답 스트림
      ↓
[폰 화면 실시간 업데이트]
```

---

## 구현 상세

### 1. bns_broadcast.fl (신규, ~120줄)

```freeLang
module bns_broadcast {
    use concurrent;

    const MAX_SUBSCRIBERS: i32 = 10;
    const MAX_EVENTS:      i32 = 256;

    // 전역 이벤트 풀 (string → i64 인덱스로 Channel 전달)
    let g_event_pool: [string];     // 이벤트 JSON 저장
    let g_event_count: i32 = 0;

    // 구독자 채널 배열 (SSE 연결마다 1개)
    let g_subscriber_channels: [concurrent.Channel];
    let g_subscriber_count: i32 = 0;

    func broadcast_init()
    func broadcast_subscribe() -> (concurrent.Channel, i32)  // 채널 + 구독자 ID
    func broadcast_unsubscribe(id: i32)
    func broadcast_event(event_json: string)  // 모든 구독자에 전파
    func broadcast_get_event(idx: i64) -> string  // 풀에서 이벤트 꺼내기
}
```

**브로드캐스트 로직:**
```freeLang
func broadcast_event(event_json: string) {
    // 이벤트 풀에 저장
    let idx = g_event_count;
    g_event_pool[idx] = event_json;
    g_event_count = g_event_count + 1;

    // 모든 구독자 채널에 인덱스 전송
    let i = 0;
    for i = 0; i < g_subscriber_count; i = i + 1 {
        g_subscriber_channels[i].chan_send(idx as i64);
    }
}
```

### 2. bns_webhook.fl (신규, ~150줄)

```freeLang
module bns_webhook {
    use bns_models;
    use bns_broadcast;

    // Gogs push 이벤트 JSON 파싱
    // 실제 payload: {"ref": "refs/heads/master", "commits": [...], "repository": {...}}
    func parse_gogs_payload(body: string) -> bns_models.GogsCommit

    // X-Gogs-Event 헤더 확인
    func is_push_event(headers: [string]) -> bool

    // 서명 검증 (간소화: Secret 토큰 비교)
    func verify_signature(headers: [string], secret: string) -> bool

    // 웹훅 처리 진입점
    func handle_webhook(req: bns_models.HttpRequest) -> bns_models.HttpResponse
}
```

**JSON 파싱 핵심:**
```freeLang
// 간단한 키-값 추출 (regex 없이)
// {"ref": "refs/heads/master", "commits": [{"id": "abc123", "message": "feat: ..."}]}

func extract_json_string(json: string, key: string) -> string {
    // '"key": "' 패턴 찾기 → 값 끝까지 추출
    let search = "\"" + key + "\": \"";
    let start_idx = bns_http.index_of(json, search);
    if start_idx < 0 { return ""; }
    let value_start = start_idx + len(search);
    let end_idx = bns_http.index_of_from(json, "\"", value_start);
    if end_idx < 0 { return ""; }
    return bns_http.substring(json, value_start, end_idx);
}
```

### 3. bns_server.fl 수정

**API 이름 수정 (channel_* → chan_*):**
```freeLang
// 변경 전
g_request_channel = concurrent.channel_new(64);
concurrent.channel_send(g_request_channel, request);
let msg = concurrent.channel_recv(g_response_channel, 0);

// 변경 후
g_request_channel = concurrent.chan_new(64);
g_request_channel.chan_send(idx as i64);      // 문자열은 풀 인덱스로
let (idx, ok) = g_response_channel.chan_recv();
```

**Webhook 라우트 추가:**
```freeLang
} else if req.method == "POST" && req.path == "/webhook/gogs" {
    return bns_webhook.handle_webhook(req);
}
```

### 4. bns_handlers.fl 수정 (handle_feed 개선)

```freeLang
// 변경 전: 하드코딩 1회 SSE
func handle_feed() -> bns_models.HttpResponse {
    let event_data = "...하드코딩...";
    return bns_models.http_response_sse(event_data);
}

// 변경 후: 브로드캐스트 채널 구독
func handle_feed() -> bns_models.HttpResponse {
    // 구독자 채널 등록
    let (sub_ch, sub_id) = bns_broadcast.broadcast_subscribe();

    // 채널에서 이벤트 수신 (100 tick 폴링)
    let i = 0;
    for i = 0; i < 100; i = i + 1 {
        let (idx, ok) = sub_ch.chan_recv();
        if ok {
            let event_json = bns_broadcast.broadcast_get_event(idx);
            bns_broadcast.broadcast_unsubscribe(sub_id);
            return bns_models.http_response_sse(event_json);
        }
    }

    // 타임아웃: 현재 최신 이벤트 반환
    bns_broadcast.broadcast_unsubscribe(sub_id);
    let latest = bns_broadcast.broadcast_get_latest();
    return bns_models.http_response_sse(latest);
}
```

---

## 수정 대상 파일

```
projects/bns-server/
├── bns_broadcast.fl   ← 신규 (브로드캐스트 관리)
├── bns_webhook.fl     ← 신규 (Gogs webhook 수신)
├── bns_server.fl      ← 수정 (API 이름 + webhook 라우트)
└── bns_handlers.fl    ← 수정 (handle_feed 실시간 스트리밍)
```

**참고 파일 (재사용):**
- `projects/bns-server/bns_http.fl` — `index_of`, `substring` 헬퍼 재사용
- `freelang-zero-copy-db/stdlib/concurrent.fl` — `chan_new`, `chan_send`, `chan_recv`
- `freelang-zero-copy-db/pkg/gogs/webhook_config.fl` — `WebhookPayload` 구조체 참고
- `.claude/missions/mission1-gogs-pulse/pulse.sh` — Gogs API 토큰 패턴

---

## 검증 방법

### 1. Webhook 수신 확인 (bash로 시뮬레이션)
```bash
# Gogs push 이벤트 시뮬레이션
echo '{"ref":"refs/heads/master","commits":[{"id":"abc123","message":"test commit"}]}' \
  | python3 -c "
import sys, json
data = json.load(sys.stdin)
commit = data['commits'][0]
print(f'hash: {commit[\"id\"][:7]}')
print(f'msg:  {commit[\"message\"]}')
"
```

### 2. SSE 이벤트 형식 확인
```bash
# SSE 포맷 검증
echo 'data: {"repo":"zero-copy-db","commit":"abc123","message":"test"}'
echo ""
```

### 3. 브로드캐스트 흐름 검증
```
broadcast_event("..JSON..") 호출
→ g_event_pool에 저장 확인
→ g_subscriber_channels 배열 순회 확인
→ handle_feed() 폴링 수신 확인
```

### 4. 코드 파일 수 및 라인 수 검증
```
기존: 730줄 (4파일)
추가: ~270줄 (2파일)
합계: ~1,000줄 (6파일)
```

---

## 주의사항

- Channel 버퍼는 `[i64]`이므로 문자열 직접 전송 불가 → 전역 풀 인덱스 패턴 필수
- HMAC-SHA256 복잡도 이유로 `verify_signature`는 간소화 (Secret 존재 여부만 체크)
- SSE 지속 연결은 Channel 폴링으로 시뮬레이션 (실제 스트리밍은 Phase 3)
- 브로드캐스트 구독자 최대 10개 제한 (MAX_SUBSCRIBERS)

