func parse_memory_summary(content: string) -> string {
    // "Phase 11" 패턴 찾기
    let zdb_phase = 11;  // fallback
    let zdb_lines = 19540;
    let compiler_phase = 8;
    let compiler_lines = 4435;

    let lines = bns_http.split_lines(content);
    let i = 0;
    for i = 0; i < len(lines); i = i + 1 {
        let line = lines[i];
        // "Zero-Copy-DB Phase" 라인
        if index_of(line, "Zero-Copy-DB Phase") >= 0 {
            zdb_phase = extract_phase_number(line);
        }
        // "총 규모: N줄" 라인
        if index_of(line, "총 규모") >= 0 && index_of(line, "줄") >= 0 {
            zdb_lines = extract_line_count(line);
        }
    }
    // JSON 조립
    let json = "{\"zdb_phase\":" + to_string(zdb_phase) + ",";
    json = json + "\"zdb_lines\":" + to_string(zdb_lines) + "}";
    return json;
}
