    }

    // === 헬퍼: 정수를 문자열로 ===
    @inline
    func to_string(n: i32) -> string {
        if n == 0 {
            return "0";
        }

        let negative = false;
        if n < 0 {
            negative = true;
            n = 0 - n;
        }

        let result = "";
        let temp = n;

        for temp > 0 {
            let digit = temp % 10;
