  void initState() {
    super.initState();
    _futureGogs = ApiService.fetchGogs();
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(
        title: const Text('🔧 Recent Commits'),
        backgroundColor: Colors.black,
      ),
      body: FutureBuilder<ApiGogsResponse>(
        future: _futureGogs,
